// Lifecycle state of a River job. A job becomes available or scheduled, turns running while a worker
// holds it, and ends in completed, cancelled or discarded.
// Ref: #/components/schemas/JobState
type JobState string

const (
	JobStateAvailable JobState = "available"
	JobStateCancelled JobState = "cancelled"
	JobStateCompleted JobState = "completed"
	JobStateDiscarded JobState = "discarded"
	JobStatePending   JobState = "pending"
	JobStateRetryable JobState = "retryable"
	JobStateRunning   JobState = "running"
	JobStateScheduled JobState = "scheduled"
)

// AllValues returns all JobState values.
func (JobState) AllValues() []JobState {
	return []JobState{
		JobStateAvailable,
		JobStateCancelled,
		JobStateCompleted,
		JobStateDiscarded,
		JobStatePending,
		JobStateRetryable,
		JobStateRunning,
		JobStateScheduled,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s JobState) MarshalText() ([]byte, error) {
	switch s {
	case JobStateAvailable:
		return []byte(s), nil
	case JobStateCancelled:
		return []byte(s), nil
	case JobStateCompleted:
		return []byte(s), nil
	case JobStateDiscarded:
		return []byte(s), nil
	case JobStatePending:
		return []byte(s), nil
	case JobStateRetryable:
		return []byte(s), nil
	case JobStateRunning:
		return []byte(s), nil
	case JobStateScheduled:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *JobState) UnmarshalText(data []byte) error {
	switch JobState(data) {
	case JobStateAvailable:
		*s = JobStateAvailable
		return nil
	case JobStateCancelled:
		*s = JobStateCancelled
		return nil
	case JobStateCompleted:
		*s = JobStateCompleted
		return nil
	case JobStateDiscarded:
		*s = JobStateDiscarded
		return nil
	case JobStatePending:
		*s = JobStatePending
		return nil
	case JobStateRetryable:
		*s = JobStateRetryable
		return nil
	case JobStateRunning:
		*s = JobStateRunning
		return nil
	case JobStateScheduled:
		*s = JobStateScheduled
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

